#include <iostream>

int main() {
    // Exercise 2.32: BMI Calculator (Imperial formula with int as specified in Ch. 2)
    int weightInPounds = 0;
    int heightInInches = 0;
    if (std::cin >> weightInPounds >> heightInInches) {
        int bmi = (weightInPounds * 703) / (heightInInches * heightInInches);
        std::cout << "Your BMI is: " << bmi << "\n\n";
        std::cout << "BMI VALUES\n"
                  << "Underweight: less than 18.5\n"
                  << "Normal:      between 18.5 and 24.9\n"
                  << "Overweight:  between 25 and 29.9\n"
                  << "Obese:       30 or greater\n\n";
    }

    // Exercise 2.33: Car-Pool Savings Calculator
    int miles = 0;
    int costPerGallon = 0;
    int milesPerGallon = 1;
    int parkingFees = 0;
    int tolls = 0;
    if (std::cin >> miles >> costPerGallon >> milesPerGallon >> parkingFees >> tolls) {
        int dailyCost = (miles * costPerGallon) / milesPerGallon + parkingFees + tolls;
        std::cout << "Daily driving cost: " << dailyCost << "\n";
    }
    return 0;
}
